const text = String($json.output ?? '').replace(/\r/g, '');

const priorityMatch = text.match(/^\s*PRIORITY:\s*(Low|Medium|High)\s*$/im);
const categoryMatch = text.match(/^\s*CATEGORY:\s*(Billing|Technical Support|Account|Sales|Complaint|General Inquiry|Other)\s*$/im)
  || text.match(/^\s*Category:\s*(Billing|Technical Support|Account|Sales|Complaint|General Inquiry|Other)\s*$/im);

const summaryMatch = text.match(/^\s*SUMMARY:\s*(.*?)\s*(?=^\s*REPLY:\s*$)/ims)
  || text.match(/^\s*Summary:\s*(.*?)\s*(?=^\s*Reply:\s*$)/ims);

const replyMatch = text.match(/^\s*REPLY:\s*([\s\S]*)$/im)
  || text.match(/^\s*Reply:\s*([\s\S]*)$/im);

const priority = priorityMatch?.[1] ?? 'Unknown';
const category = categoryMatch?.[1]?.trim() ?? 'Unknown';
const summary = summaryMatch?.[1]?.trim() ?? 'Unknown';
const reply = replyMatch?.[1]?.trim() ?? '';

const valid =
  ['Low', 'Medium', 'High'].includes(priority) &&
  ['Billing', 'Technical Support', 'Account', 'Sales', 'Complaint', 'General Inquiry', 'Other'].includes(category) &&
  summary !== 'Unknown' &&
  reply.length > 0;

return [{
  json: {
    subject: $json.subject ?? '',
    body: $json.body ?? '',
    sender_email: $json.sender_email ?? '',
    ai_output: text,
    priority,
    category,
    summary,
    reply,
    valid_format: valid
  }
}];

const item = $json;

return [{
  json: {
    success: item.valid_format !== false,
    processed_at: new Date().toISOString(),
    subject: $('Edit Fields').first().json.subject || '',
    sender_email: item.sender_email || '',
    priority: item.priority || 'Unknown',
    category: item.category || 'Unknown',
    summary: item.summary || 'Unknown',
    reply: item.reply || '',
    priority_status: item.priority_status || 'NORMAL',
    action: item.action || 'Review manually',
    status: item.status || 'Needs Review',
    needs_escalation: item.priority === 'High',
    ai_output: item.ai_output || ''
  }
}];
